/**
 * Agent - Pathfinding Agent Configuration
 *
 * Main thread interface for the physics worker's AgentController.
 * Exposes `steering` property for SteeringBehavior access.
 *
 * **Properties**
 *
 * - `steering` - Steering behavior configuration (Steering instance)
 * - `replanThreshold` - Time blocked before replanning (default: 2.0)
 * - `rotationSpeed` - Rotation interpolation speed (default: 0.15)
 * - `maxPathRetries` - Maximum path retry attempts (default: 10)
 * - `groundOffset` - Height offset above ground (default: 1.0)
 *
 * **Usage**
 *
 * ```js
 * body.agent.rotationSpeed = 0.2;
 * body.agent.set({ maxSpeed: 8, replanThreshold: 3.0 });
 * ```
 *
 * @class Agent
 * @short Pathfinding agent configuration interface
 * @category Core
 * @tags Pathfinding, Agent, Configuration
 */
export class Agent {
    /**
     * Create agent configuration interface.
     *
     * @param {KinematicBody} kinematicBody - Parent kinematic body.
     */
    constructor(kinematicBody: KinematicBody);
    _kinematicBody: KinematicBody;
    _physics: any;
    _bodyIndex: any;
    _replanThreshold: number;
    _rotationSpeed: number;
    _maxPathRetries: number;
    _groundOffset: number;
    /**
     * Steering behavior configuration.
     *
     * @type {Steering}
     */
    steering: Steering;
    set replanThreshold(value: number);
    /**
     * Time blocked before replanning path (seconds).
     *
     * @type {number}
     * @default 2.0
     */
    get replanThreshold(): number;
    set rotationSpeed(value: number);
    /**
     * Rotation interpolation speed (0-1).
     *
     * @type {number}
     * @default 0.15
     */
    get rotationSpeed(): number;
    set maxPathRetries(value: number);
    /**
     * Maximum path retry attempts.
     *
     * @type {number}
     * @default 10
     */
    get maxPathRetries(): number;
    set groundOffset(value: number);
    /**
     * Height offset above ground for kinematic bodies.
     *
     * @type {number}
     * @default 1.0
     */
    get groundOffset(): number;
    /**
     * Configure multiple agent parameters at once.
     *
     * Steering properties (maxSpeed, arrivalRadius, etc.) are forwarded
     * to the steering behavior automatically.
     *
     * @param {Object} config - Configuration object.
     * @param {number} [config.maxSpeed] - Maximum movement speed (steering).
     * @param {number} [config.arrivalRadius] - Arrival distance (steering).
     * @param {number} [config.avoidanceRadius] - Avoidance radius (steering).
     * @param {number} [config.separationRadius] - Agent separation distance (steering).
     * @param {number} [config.separationForce] - Agent separation strength (steering).
     * @param {number} [config.replanThreshold] - Replan time threshold.
     * @param {number} [config.rotationSpeed] - Rotation interpolation speed.
     * @param {number} [config.maxPathRetries] - Max path retries.
     * @param {number} [config.groundOffset] - Height above ground.
     * @returns {Agent} This instance for chaining.
     */
    set(config: {
        maxSpeed?: number;
        arrivalRadius?: number;
        avoidanceRadius?: number;
        separationRadius?: number;
        separationForce?: number;
        replanThreshold?: number;
        rotationSpeed?: number;
        maxPathRetries?: number;
        groundOffset?: number;
    }): Agent;
    /**
     * Send configuration update to physics worker.
     *
     * @param {Object} config - Configuration to send.
     * @private
     */
    private _syncToWorker;
    /**
     * Initialize agent with configuration values.
     *
     * @param {Object} config - Initial configuration.
     * @private
     */
    private _initWithConfig;
}
/**
 * Agent - Main Thread Agent Controller Interface
 *
 * Provides a main-thread interface for controlling pathfinding agents.
 * Property changes are immediately synchronized to the physics worker.
 *
 * **Features**
 *
 * - Direct property access with automatic worker sync
 * - Chainable `set()` method for batch configuration
 * - Nested `steering` object for movement parameters
 *
 * **Usage**
 *
 * ```js
 * // Direct property access
 * body.agent.steering.maxSpeed = 10;
 * body.agent.rotationSpeed = 0.2;
 *
 * // Chainable batch configuration
 * body.agent.set({ maxSpeed: 8, rotationSpeed: 0.2 });
 * body.agent.steering.set({ arrivalRadius: 2.0, slowdownRadius: 5.0 });
 * ```
 *
 * @module @three-blocks/pro/core/Agent
 * @class Agent
 * @short Main thread interface for pathfinding agents
 * @category Core
 * @tags Pathfinding, Agent, Configuration
 */
/**
 * Steering - Main Thread Steering Behavior Interface
 *
 * Provides access to steering behavior parameters for pathfinding agents.
 * All property changes are immediately synchronized to the physics worker.
 *
 * **Properties**
 *
 * - `maxSpeed` - Maximum movement speed (default: 5.0)
 * - `maxForce` - Maximum steering force (default: 10.0)
 * - `arrivalRadius` - Distance to consider arrived at waypoint (default: 0.8)
 * - `slowdownRadius` - Distance to start slowing down (default: 4.0)
 * - `avoidanceRadius` - Obstacle detection radius (default: 1.5)
 * - `lookAheadDistance` - Raycast distance for avoidance (default: 3.0)
 * - `separationRadius` - Distance at which agents push apart (default: 2.0)
 * - `separationForce` - Strength of agent separation (default: 5.0)
 *
 * **Usage**
 *
 * ```js
 * body.agent.steering.maxSpeed = 10;
 * body.agent.steering.separationRadius = 3.0;
 * body.agent.steering.set({ arrivalRadius: 2.0, separationForce: 8.0 });
 * ```
 *
 * @class Steering
 * @short Steering behavior configuration interface
 * @category Core
 * @tags Steering, Configuration, Movement, Separation
 */
export class Steering {
    /**
     * Create steering configuration interface.
     *
     * @param {Agent} agent - Parent agent instance.
     */
    constructor(agent: Agent);
    _agent: Agent;
    _maxSpeed: number;
    _maxForce: number;
    _arrivalRadius: number;
    _slowdownRadius: number;
    _avoidanceRadius: number;
    _lookAheadDistance: number;
    _separationRadius: number;
    _separationForce: number;
    set maxSpeed(value: number);
    /**
     * Maximum movement speed.
     *
     * @type {number}
     * @default 5.0
     */
    get maxSpeed(): number;
    set maxForce(value: number);
    /**
     * Maximum steering force.
     *
     * @type {number}
     * @default 10.0
     */
    get maxForce(): number;
    set arrivalRadius(value: number);
    /**
     * Distance to consider arrived at waypoint.
     *
     * @type {number}
     * @default 0.8
     */
    get arrivalRadius(): number;
    set slowdownRadius(value: number);
    /**
     * Distance to start slowing down.
     *
     * @type {number}
     * @default 4.0
     */
    get slowdownRadius(): number;
    set avoidanceRadius(value: number);
    /**
     * Obstacle detection radius.
     *
     * @type {number}
     * @default 1.5
     */
    get avoidanceRadius(): number;
    set lookAheadDistance(value: number);
    /**
     * Raycast distance for avoidance.
     *
     * @type {number}
     * @default 3.0
     */
    get lookAheadDistance(): number;
    set separationRadius(value: number);
    /**
     * Distance at which agents push apart from each other.
     *
     * @type {number}
     * @default 2.0
     */
    get separationRadius(): number;
    set separationForce(value: number);
    /**
     * Strength of agent separation force.
     *
     * @type {number}
     * @default 5.0
     */
    get separationForce(): number;
    /**
     * Configure multiple steering parameters at once.
     *
     * @param {Object} config - Configuration object.
     * @param {number} [config.maxSpeed] - Maximum movement speed.
     * @param {number} [config.maxForce] - Maximum steering force.
     * @param {number} [config.arrivalRadius] - Distance to consider arrived.
     * @param {number} [config.slowdownRadius] - Distance to start slowing.
     * @param {number} [config.avoidanceRadius] - Obstacle detection radius.
     * @param {number} [config.separationRadius] - Agent separation distance.
     * @param {number} [config.separationForce] - Agent separation strength.
     * @param {number} [config.lookAheadDistance] - Raycast distance.
     * @returns {Steering} This instance for chaining.
     */
    set(config: {
        maxSpeed?: number;
        maxForce?: number;
        arrivalRadius?: number;
        slowdownRadius?: number;
        avoidanceRadius?: number;
        separationRadius?: number;
        separationForce?: number;
        lookAheadDistance?: number;
    }): Steering;
}
